package com.tuxcompose

import androidx.compose.ui.geometry.Rect
import com.tuxcompose.layout.*
import java.io.File
import kotlin.test.*

/** Results generated by unmodified alphaTab classes, not a reimplementation in the harness. */
class AlphaTabOracleTest {
    private fun records()=File(System.getProperty("tux.compose.upstream.fixtures")).readLines()
        .filterNot {it.isBlank() || it.startsWith("#")}.map {it.split('\t')}
    @Test fun skylineQueriesAndCanonicalSegmentsMatchActualAlphaTabFor2048Insertions() {
        var skyline: TGSkyline?=null;var count=0
        records().forEach {r->when(r[0]) {
            "reset"->skyline=TGSkyline(r[1].toFloat(),r[2].toFloat())
            "sky"->{val s=skyline!!;s.reserve(r[1].toFloat(),r[2].toFloat(),r[3].toFloat())
                assertEquals(r[6].toFloat(),s.maximum(r[4].toFloat(),r[5].toFloat()),"record $count")
                assertEquals(r[7].toInt(),s.segmentCount,"canonical segments at $count");count++}
        }}
        assertEquals(2048,count)
    }
    @Test fun hardRodWaterFillingMatches400ActualAlphaTabForceSolutionsWithoutSqueezing() {
        var count=0
        records().filter {it[0]=="spring"}.forEach {r->
            val minimum=r[1].split(',').map {it.toFloat()};val weights=r[2].split(',').map {it.toDouble()}
            val result=distributeSprings(minimum,weights,r[3].toFloat())
            val expected=r[4].split(',').map {it.toFloat()}
            assertEquals(expected.size,result.size)
            result.indices.forEach {i->assertEquals(expected[i],result[i],.001f,"record $count spring $i")}
            count++
        }
        assertEquals(400,count)
    }
    @Test fun accidentalColumnPackingMatches128ActualAlphaTabGlyphGroups() {
        var count=0
        records().filter {it[0]=="columns"}.forEach {r->
            val boxes=r[1].split(';').map {s->val p=s.split(',').map {it.toFloat()};Rect(0f,p[0],8f,p[0]+p[1])}
            assertEquals(r[2].split(',').map {it.toInt()},packScoreColumns(boxes),"group $count")
            count++
        }
        assertEquals(128,count)
    }
}
